// UpdatedAtLTE applies the LTE predicate on the "updated_at" field.
func UpdatedAtLTE(v time.Time) predicate.DirectorySource {
	return predicate.DirectorySource(sql.FieldLTE(FieldUpdatedAt, v))
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DirectorySource) predicate.DirectorySource {
	return predicate.DirectorySource(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DirectorySource) predicate.DirectorySource {
	return predicate.DirectorySource(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DirectorySource) predicate.DirectorySource {
	return predicate.DirectorySource(sql.NotPredicates(p))
}
